    30→import 'package:ioh_ide_mobile/view/global_controller/global_profile_controller.dart';
    31→import 'package:path_provider/path_provider.dart';
    32→
    33→class AppDio with DioMixin implements Dio {
    34→  static Future<AppDio> create() async {
    35→    final dio = AppDio._();
    36→    await dio._init();
    37→    return dio;
    38→  }
    39→
    40→  late PersistCookieJar cookieJar;
    41→  final _localAuthDataSource = Get.find<LocalAuthDataSource>();
    42→  bool _isLoggingOut = false;
    43→
    44→  AppDio._() {
    45→    options = BaseOptions(
    46→      connectTimeout: const Duration(seconds: 120),
    47→      receiveTimeout: const Duration(seconds: 120),
    48→      sendTimeout: const Duration(seconds: 120),
    49→      headers: {
    50→        'Content-Type': 'application/json',
    51→      },
    52→    );
    53→
    54→    httpClientAdapter = HttpClientAdapter();
    55→  }
    56→
    57→  Future<void> _init() async {
    58→    final dir = await getApplicationDocumentsDirectory();
    59→    cookieJar = PersistCookieJar(
    60→      ignoreExpires: false,
    61→      storage: FileStorage('${dir.path}/.cookies'),
    62→    );
    63→
    64→    interceptors.addAll([
    65→      if (!kReleaseMode) ChuckerHelper.instance.dioInterceptor,
    66→      CookieManager(cookieJar),
    67→      _interceptor(),
    68→    ]);
    69→  }
    70→
    71→  InterceptorsWrapper _interceptor() => InterceptorsWrapper(
    72→    onRequest: _handleRequest,
    73→    onResponse: _handleResponse,
    74→    onError: _handleError,
    75→  );
    76→
    77→  Future<void> _handleRequest(RequestOptions options, RequestInterceptorHandler handler) async {
    78→    String token = "";
    79→
    80→    if (AuthorizationTokenSource.notificationPaths.contains(options.path)) {
    81→      token = await _localAuthDataSource.getNotificationToken();
    82→    } else if (options.uri.toString().contains(dotenv.get("BASE_URL_TOKO"))) {
    83→      token = await _localAuthDataSource.getTokoToken();
    84→    } else if (options.uri.toString().contains("${dotenv.get('BASE_URL')}/sso")) {
    85→      token = await _localAuthDataSource.getAuth0Token();
    86→    } else if (options.uri.toString().contains("${dotenv.get('BASE_URL')}/notification")) {
    87→      token = await _localAuthDataSource.getNotificationToken();
    88→    } else {
    89→      token = await _localAuthDataSource.getCMSToken();
    90→    }
    91→
    92→    if (token.isNotEmpty) {
    93→      options.headers['Authorization'] = 'Bearer $token';
    94→    }
    95→
    96→    if (options.data is FormData) {
    97→      options.headers['Content-Type'] = 'multipart/form-data';
    98→    }
    99→
   100→    options.headers['Accept-Language'] = Get.locale?.languageCode;
   101→    options.headers['Accept'] = 'application/json';
   102→    options.headers['Accept-Encoding'] = 'identity';
   103→    options.headers['Content-Length'] = null;
   104→
   105→    try {
   106→      List<Cookie> cookies = await cookieJar.loadForRequest(options.uri);
   107→
   108→      final seen = <String, Cookie>{};
   109→      for (var cookie in cookies.reversed) {
   110→        seen[cookie.name] = cookie;
   111→      }
   112→
   113→      for (var cookie in seen.values) {
   114→        switch (cookie.name) {
   115→          case 'x-csrf-token':
   116→          case 'kvsToken.Portal':
   117→          case 'kvsToken.Business':
   118→            options.headers[cookie.name] = cookie.value;
   119→            break;
   120→        }
   121→      }
   122→    } catch (e) {
   123→      if (kDebugMode) Get.log('Failed to load cookies: $e');
   124→    }
   125→    options.headers.remove('cookie');
   126→    handler.next(options);
   127→  }
   128→
   129→  Future<void> _handleResponse(Response response, ResponseInterceptorHandler handler) async {
   130→    if (response.requestOptions.path.contains("/sso/api/v1/oauth/token/revoke")) {
   131→      await cookieJar.deleteAll();
   132→    }
   133→    handler.next(response);
   134→  }
   135→
   136→  Future<void> _handleError(DioException error, ErrorInterceptorHandler handler) async {
   137→    final requestOptions = error.requestOptions;
   138→
   139→    final redirectToErrorPage = _getExtra(requestOptions)[MapKey.redirectToErrorPage] ?? false;
   140→
   141→    // Check for NO INTERNET (connectionError / SocketException)
   142→    if (error.type == DioExceptionType.connectionError
   143→        || error.error is SocketException
   144→        || (error.response?.statusCode == StatusCode.badRequest.code && DioErrorSource.handleBadRequest(requestOptions.path)
   145→        || (error.response?.statusCode == StatusCode.notFound.code && redirectToErrorPage))
   146→    ) {
   147→      final queued = QueuedRequest(request: requestOptions);
   148→      RequestQueueService().add(queued);
   149→
   150→      if (error.type == DioExceptionType.connectionError || error.error is SocketException ) {
   151→        if (Get.currentRoute != AppRoute.noInternet) {
   152→          Get.toNamed(AppRoute.noInternet);
   153→        }
   154→      } else if (error.response?.statusCode == StatusCode.badRequest.code && DioErrorSource.handleBadRequest(requestOptions.path)
   155→          || (error.response?.statusCode == StatusCode.notFound.code && redirectToErrorPage)) {
   156→        if (RequestQueueService().retryCount >= DioErrorSource.maxRetry) {
   157→          RequestQueueService().retryCount = 0;
   158→
   159→          if (Get.currentRoute != AppRoute.helpCenter) {
   160→            if (Get.currentRoute != AppRoute.dashboard) {
   161→              Get.offNamed(AppRoute.helpCenter);
   162→            } else {
   163→              Get.toNamed(AppRoute.helpCenter);
   164→            }
   165→          }
   166→        } else if (Get.currentRoute != AppRoute.errorOccurred) {
   167→          Get.toNamed(AppRoute.errorOccurred);
   168→        }
   169→      }
   170→
   171→      try {
   172→        final response = await queued.completer.future;
   173→        return handler.resolve(response);
   174→      } catch (e) {
   175→        return handler.reject(DioException(
   176→          requestOptions: requestOptions,
   177→          error: e,
   178→          type: DioExceptionType.unknown,
   179→        ));
   180→      }
   181→    }
   182→
   183→    // Check UNAUTHORIZED
   184→    if (error.response?.statusCode == StatusCode.unauthorized.code && !RequestQueueService().hasRequests) {
   185→      try {
   186→        if (requestOptions.path.contains("/oauth/token")
   187→            || AuthEndPoint.mfaEndPoints.contains(requestOptions.path)) {
   188→          return handler.next(error);
   189→        }
   190→
   191→        String? newAccessToken = await TokenRefreshService().refreshTokenIfNeeded(() async {
   192→          if (AuthorizationTokenSource.notificationPaths.contains(requestOptions.path)) {
   193→            final data = await Get.find<AuthRepository>().getAuthorizeNotificationToken();
   194→            String token = DefaultValue.empty;
   195→            data.success((data) {
   196→              token = data.token ?? DefaultValue.empty;
   197→            });
   198→            return token;
   199→          } else if (requestOptions.baseUrl.contains(dotenv.get("BASE_URL_TOKO"))) {
   200→            final data = await Get.find<AuthRepository>().exchangeTokoToken();
   201→            String token = DefaultValue.empty;
   202→            data.success((data) {
   203→              token = data.token ?? DefaultValue.empty;
   204→            });
   205→            return token;
   206→          } else if (requestOptions.uri.toString().contains("${dotenv.get('BASE_URL')}/sso")) {
   207→            final refreshToken = await _localAuthDataSource.getAuth0RefreshToken();
   208→            final newToken = await Auth0Service.instance.refreshToken(
   209→              refreshToken: refreshToken,
   210→            );
   211→
   212→            await _localAuthDataSource.setAuth0Token(newToken.accessToken);
   213→            await _localAuthDataSource.setAuth0IdToken(newToken.idToken);
   214→            if (newToken.refreshToken != null) {
   215→              await _localAuthDataSource.setAuth0RefreshToken(newToken.refreshToken);
   216→            }
   217→            return newToken.accessToken;
   218→          } else if (requestOptions.uri.toString().contains("${dotenv.get('BASE_URL')}/notification")) {
   219→            final data = await Get.find<AuthRepository>().getAuthorizeNotificationToken();
   220→            String token = DefaultValue.empty;
   221→            data.success((data) {
   222→              token = data.token ?? DefaultValue.empty;
   223→            });
   224→            return token;
   225→          } else {
   226→            final data = await Get.find<AuthRepository>().getAuthorizeCMSToken();
   227→            String token = DefaultValue.empty;
   228→            data.success((data) {
   229→              token = data.token ?? DefaultValue.empty;
   230→            });
   231→            return token;
   232→          }
   233→        });
   234→
   235→        if (newAccessToken.isEmpty) {
   236→          handler.reject(error);
   237→          _logoutUser();
   238→          return;
   239→        }
   240→
   241→        // Clone the request with updated Authorization header
   242→        if (requestOptions.data is Map<String, dynamic>) {
   243→          final data = requestOptions.data as Map<String, dynamic>;
   244→
   245→          if (data.containsKey("id_token")) {
   246→            data["id_token"] = await _localAuthDataSource.getAuth0IdToken();
   247→            requestOptions.data = data;
   248→          }
   249→        }
   250→        requestOptions.headers['Authorization'] = 'Bearer $newAccessToken';
   251→
   252→        final opts = Options(
   253→          method: requestOptions.method,
   254→          headers: {
   255→            ...requestOptions.headers,
   256→          },
   257→        );
   258→
   259→        options.baseUrl = requestOptions.baseUrl;
   260→        for(var entry in requestOptions.headers.entries) {
   261→          options.headers[entry.key] = entry.value;
   262→        }
   263→
   264→        final cloneReq = await request(
   265→          requestOptions.path,
   266→          data: requestOptions.data,
   267→          queryParameters: requestOptions.queryParameters,
   268→          options: opts,
   269→        );
