import 'dart:io';

import 'package:cookie_jar/cookie_jar.dart';
import 'package:dio/dio.dart';
import 'package:dio_cookie_manager/dio_cookie_manager.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:get/get.dart' hide FormData, Response;
import 'package:ioh_ide_mobile/app/app_routes.dart';
import 'package:ioh_ide_mobile/core/constants/dio_error_source.dart';
import 'package:ioh_ide_mobile/core/constants/default_value.dart';
import 'package:ioh_ide_mobile/core/constants/map_key.dart';
import 'package:ioh_ide_mobile/core/constants/network/authorization_token_source.dart';
import 'package:ioh_ide_mobile/core/constants/network/data_source/auth_end_point.dart';
import 'package:ioh_ide_mobile/core/enums/bottom_navigation_type.dart';
import 'package:ioh_ide_mobile/core/enums/status_code.dart';
import 'package:ioh_ide_mobile/core/services/auth0/auth0_service.dart';
import 'package:ioh_ide_mobile/core/services/queue_request/queue_request.dart';
import 'package:ioh_ide_mobile/core/services/queue_request/request_queue_service.dart';
import 'package:ioh_ide_mobile/core/services/refresh_token/refresh_token_service.dart';
import 'package:ioh_ide_mobile/core/utils/chucker_helper.dart';
import 'package:ioh_ide_mobile/core/utils/data_state.dart';
import 'package:ioh_ide_mobile/data/data_sources/local/auth/local_auth_data_source.dart';
import 'package:ioh_ide_mobile/core/annotations/interceptor_only.dart';
import 'package:ioh_ide_mobile/data/data_sources/network/network_error.dart';
import 'package:ioh_ide_mobile/data/repositories/auth/auth_repository.dart';
import 'package:ioh_ide_mobile/view/features/dashboard/dashboard_controller.dart';
import 'package:ioh_ide_mobile/view/global_controller/global_cart_controller.dart';
import 'package:ioh_ide_mobile/view/global_controller/global_order_controller.dart';
import 'package:ioh_ide_mobile/view/global_controller/global_profile_controller.dart';
import 'package:path_provider/path_provider.dart';

class AppDio with DioMixin implements Dio {
  static Future<AppDio> create() async {
    final dio = AppDio._();
    await dio._init();
    return dio;
  }

  late PersistCookieJar cookieJar;
  final _localAuthDataSource = Get.find<LocalAuthDataSource>();
  bool _isLoggingOut = false;

  AppDio._() {
    options = BaseOptions(
      connectTimeout: const Duration(seconds: 120),
      receiveTimeout: const Duration(seconds: 120),
      sendTimeout: const Duration(seconds: 120),
      headers: {
        'Content-Type': 'application/json',
      },
    );

    httpClientAdapter = HttpClientAdapter();
  }

  Future<void> _init() async {
    final dir = await getApplicationDocumentsDirectory();
    cookieJar = PersistCookieJar(
      ignoreExpires: false,
      storage: FileStorage('${dir.path}/.cookies'),
    );

    interceptors.addAll([
      if (!kReleaseMode) ChuckerHelper.instance.dioInterceptor,
      CookieManager(cookieJar),
      _interceptor(),
    ]);
  }

  InterceptorsWrapper _interceptor() => InterceptorsWrapper(
    onRequest: _handleRequest,
    onResponse: _handleResponse,
    onError: _handleError,
  );

  Future<void> _handleRequest(RequestOptions options, RequestInterceptorHandler handler) async {
    String token = "";

    if (AuthorizationTokenSource.notificationPaths.contains(options.path)) {
      token = await _localAuthDataSource.getNotificationToken();
    } else if (options.uri.toString().contains(dotenv.get("BASE_URL_TOKO"))) {
      token = await _localAuthDataSource.getTokoToken();
    } else if (options.uri.toString().contains("${dotenv.get('BASE_URL')}/sso")) {
      token = await _localAuthDataSource.getAuth0Token();
    } else if (options.uri.toString().contains("${dotenv.get('BASE_URL')}/notification")) {
      token = await _localAuthDataSource.getNotificationToken();
    } else {
      token = await _localAuthDataSource.getCMSToken();
    }

    if (token.isNotEmpty) {
      options.headers['Authorization'] = 'Bearer $token';
    }

    if (options.data is FormData) {
      options.headers['Content-Type'] = 'multipart/form-data';
    }

    options.headers['Accept-Language'] = Get.locale?.languageCode;
    options.headers['Accept'] = 'application/json';
    options.headers['Accept-Encoding'] = 'identity';
    options.headers['Content-Length'] = null;

    try {
      List<Cookie> cookies = await cookieJar.loadForRequest(options.uri);

      final seen = <String, Cookie>{};
      for (var cookie in cookies.reversed) {
        seen[cookie.name] = cookie;
      }

      for (var cookie in seen.values) {
        switch (cookie.name) {
          case 'x-csrf-token':
          case 'kvsToken.Portal':
          case 'kvsToken.Business':
            options.headers[cookie.name] = cookie.value;
            break;
        }
      }
    } catch (e) {
      if (kDebugMode) Get.log('Failed to load cookies: $e');
    }
    options.headers.remove('cookie');
    handler.next(options);
  }

  Future<void> _handleResponse(Response response, ResponseInterceptorHandler handler) async {
    if (response.requestOptions.path.contains("/sso/api/v1/oauth/token/revoke")) {
      await cookieJar.deleteAll();
    }
    handler.next(response);
  }

  Future<void> _handleError(DioException error, ErrorInterceptorHandler handler) async {
    final requestOptions = error.requestOptions;

    final redirectToErrorPage = _getExtra(requestOptions)[MapKey.redirectToErrorPage] ?? false;

    // Check for NO INTERNET (connectionError / SocketException)
    if (error.type == DioExceptionType.connectionError
        || error.error is SocketException
        || (error.response?.statusCode == StatusCode.badRequest.code && DioErrorSource.handleBadRequest(requestOptions.path)
        || (error.response?.statusCode == StatusCode.notFound.code && redirectToErrorPage))
    ) {
      final queued = QueuedRequest(request: requestOptions);
      RequestQueueService().add(queued);

      if (error.type == DioExceptionType.connectionError || error.error is SocketException ) {
        if (Get.currentRoute != AppRoute.noInternet) {
          Get.toNamed(AppRoute.noInternet);
        }
      } else if (error.response?.statusCode == StatusCode.badRequest.code && DioErrorSource.handleBadRequest(requestOptions.path)
          || (error.response?.statusCode == StatusCode.notFound.code && redirectToErrorPage)) {
        if (RequestQueueService().retryCount >= DioErrorSource.maxRetry) {
          RequestQueueService().retryCount = 0;

          if (Get.currentRoute != AppRoute.helpCenter) {
            if (Get.currentRoute != AppRoute.dashboard) {
              Get.offNamed(AppRoute.helpCenter);
            } else {
              Get.toNamed(AppRoute.helpCenter);
            }
          }
        } else if (Get.currentRoute != AppRoute.errorOccurred) {
          Get.toNamed(AppRoute.errorOccurred);
        }
      }

      try {
        final response = await queued.completer.future;
        return handler.resolve(response);
      } catch (e) {
        return handler.reject(DioException(
          requestOptions: requestOptions,
          error: e,
          type: DioExceptionType.unknown,
        ));
      }
    }

    // Check UNAUTHORIZED
    if (error.response?.statusCode == StatusCode.unauthorized.code && !RequestQueueService().hasRequests) {
      try {
        if (requestOptions.path.contains("/oauth/token")
            || AuthEndPoint.mfaEndPoints.contains(requestOptions.path)) {
          return handler.next(error);
        }

        String? newAccessToken = await TokenRefreshService().refreshTokenIfNeeded(() async {
          if (AuthorizationTokenSource.notificationPaths.contains(requestOptions.path)) {
            final data = await Get.find<AuthRepository>().getAuthorizeNotificationToken();
            String token = DefaultValue.empty;
            data.success((data) {
              token = data.token ?? DefaultValue.empty;
            });
            return token;
          } else if (requestOptions.baseUrl.contains(dotenv.get("BASE_URL_TOKO"))) {
            final data = await Get.find<AuthRepository>().exchangeTokoToken();
            String token = DefaultValue.empty;
            data.success((data) {
              token = data.token ?? DefaultValue.empty;
            });
            return token;
          } else if (requestOptions.uri.toString().contains("${dotenv.get('BASE_URL')}/sso")) {
            final refreshToken = await _localAuthDataSource.getAuth0RefreshToken();
            final newToken = await Auth0Service.instance.refreshToken(
              refreshToken: refreshToken,
            );

            await _localAuthDataSource.setAuth0Token(newToken.accessToken);
            await _localAuthDataSource.setAuth0IdToken(newToken.idToken);
            if (newToken.refreshToken != null) {
              await _localAuthDataSource.setAuth0RefreshToken(newToken.refreshToken);
            }
            return newToken.accessToken;
          } else if (requestOptions.uri.toString().contains("${dotenv.get('BASE_URL')}/notification")) {
            final data = await Get.find<AuthRepository>().getAuthorizeNotificationToken();
            String token = DefaultValue.empty;
            data.success((data) {
              token = data.token ?? DefaultValue.empty;
            });
            return token;
          } else {
            final data = await Get.find<AuthRepository>().getAuthorizeCMSToken();
            String token = DefaultValue.empty;
            data.success((data) {
              token = data.token ?? DefaultValue.empty;
            });
            return token;
          }
        });

        if (newAccessToken.isEmpty) {
          handler.reject(error);
          _logoutUser();
          return;
        }

        // Clone the request with updated Authorization header
        if (requestOptions.data is Map<String, dynamic>) {
          final data = requestOptions.data as Map<String, dynamic>;

          if (data.containsKey("id_token")) {
            data["id_token"] = await _localAuthDataSource.getAuth0IdToken();
            requestOptions.data = data;
          }
        }
        requestOptions.headers['Authorization'] = 'Bearer $newAccessToken';

        final opts = Options(
          method: requestOptions.method,
          headers: {
            ...requestOptions.headers,
          },
        );

        options.baseUrl = requestOptions.baseUrl;
        for(var entry in requestOptions.headers.entries) {
          options.headers[entry.key] = entry.value;
        }

        final cloneReq = await request(
          requestOptions.path,
          data: requestOptions.data,
          queryParameters: requestOptions.queryParameters,
          options: opts,
        );

        return handler.resolve(cloneReq);
      } catch (e) {
        if (kDebugMode) {
          Get.log('Token refresh failed: $e');
        }

        handler.reject(error);

        if (e is DioException) {
          final error = DioExceptionError(cause: e);

          if (error.cause.response?.statusCode == StatusCode.unauthorized.code) {
            _logoutUser();
          }
        }

        return;
      }
    }
    handler.next(error);
  }

  Future<void> _logoutUser() async {
    if (_isLoggingOut) return;
    _isLoggingOut = true;
    try {
      await cookieJar.deleteAll();
      await _localAuthDataSource.logout();

      Get.find<GlobalProfileController>().resetData(fromLogout: true);
      Get.find<GlobalCartController>().resetData();
      Get.find<GlobalOrderController>().orderData.value = null;
      Get.until((route) => route.settings.name == AppRoute.dashboard);
      Get.find<DashboardController>().tabSelected(BottomNavigationType.home);
    } finally {
      _isLoggingOut = false;
    }
  }

  @InterceptorOnly()
  Map<String, dynamic> _getExtra(RequestOptions options) {
    return options.extra;
  }
}

import 'package:ioh_ide_mobile/core/constants/network/data_source/notification_end_point.dart';

class AuthorizationTokenSource {
  static const List<String> notificationPaths = [
    NotificationEndPointPath.registerToken,
    NotificationEndPointPath.registerDevice,
    NotificationEndPointPath.unregisterDevice,
    NotificationEndPointPath.notificationGroup,
    NotificationEndPointPath.userNotification,
    NotificationEndPointPath.setAsRead,
    NotificationEndPointPath.setAsReadAll,
    NotificationEndPointPath.delete,
    NotificationEndPointPath.deleteAll,
  ];
}

