import 'dart:async';

class TokenRefreshService {
  static final TokenRefreshService _instance = TokenRefreshService._internal();
  factory TokenRefreshService() => _instance;

  TokenRefreshService._internal();

  Completer<String>? _completer;

  Future<String> refreshTokenIfNeeded(
    Future<String> Function() refreshLogic,
  ) async {
    if (_completer != null) {
      // Another refresh is already in progress, wait for it
      return _completer!.future;
    }

    _completer = Completer();

    try {
      final newToken = await refreshLogic();
      _completer!.complete(newToken);
      return newToken;
    } catch (e) {
      _completer!.completeError(e);
      rethrow;
    } finally {
      _completer = null;
    }
  }
}

