import 'package:ioh_ide_mobile/models/responses/auth/login_model.dart';

class LocalAuthDataSource extends AppSecurePreference {
  LocalAuthDataSource(super.storage);

  static const _auth0TokenKey = 'auth0Token';
  static const _auth0RefreshTokenKey = 'auth0RefreshToken';
  static const _auth0IdTokenKey = 'auth0IdToken';
  static const _auth0UsernameKey = 'auth0Username';
  static const _tokoTokenKey = 'tokoToken';
  static const _cmsTokenKey = 'cmsToken';
  static const _notificationTokenKey = 'notificationToken';

  Future<String> getAuth0Token() async {
    return await storage.read(key: _auth0TokenKey) ?? '';
  }

  Future<void> setAuth0Token(String? token) async {
    await storage.write(key: _auth0TokenKey, value: token);
  }

  Future<String> getAuth0RefreshToken() async {
    return await storage.read(key: _auth0RefreshTokenKey) ?? '';
  }

  Future<void> setAuth0RefreshToken(String? refreshToken) async {
    await storage.write(key: _auth0RefreshTokenKey, value: refreshToken);
  }

  Future<String> getAuth0IdToken() async {
    return await storage.read(key: _auth0IdTokenKey) ?? '';
  }

  Future<void> setAuth0IdToken(String? idToken) async {
    await storage.write(key: _auth0IdTokenKey, value: idToken);
  }

  Future<String> getAuth0Username() async {
    return await storage.read(key: _auth0UsernameKey) ?? '';
  }

  Future<void> setAuth0Username(String? username) async {
    await storage.write(key: _auth0UsernameKey, value: username);
  }

  Future<String> getTokoToken() async {
    return await storage.read(key: _tokoTokenKey) ?? '';
  }

  Future<void> setTokoToken(String? token) async {
    await storage.write(key: _tokoTokenKey, value: token);
  }

  Future<String> getCMSToken() async {
    return await storage.read(key: _cmsTokenKey) ?? DefaultValue.empty;
  }

  Future<void> setCMSToken(String? token) async {
    await storage.write(key: _cmsTokenKey, value: token);
  }

  Future<String> getNotificationToken() async {
    return await storage.read(key: _notificationTokenKey) ?? DefaultValue.empty;
  }

  Future<void> setNotificationToken(String? token) async {
    await storage.write(key: _notificationTokenKey, value: token);
  }

  Future<void> logout() async {
    await storage.delete(key: _auth0TokenKey);
    await storage.delete(key: _auth0IdTokenKey);
    await storage.delete(key: _auth0RefreshTokenKey);
    await storage.delete(key: _tokoTokenKey);
    await storage.delete(key: _cmsTokenKey);
    await storage.delete(key: _notificationTokenKey);
  }

  Future<void> setLoginToken(LoginModel data) async {
    await setAuth0Token(data.token);
    await setAuth0IdToken(data.idToken);
    await setAuth0RefreshToken(data.refreshToken);
  }
}

