import 'package:ioh_ide_mobile/models/responses/empty/empty_model.dart';

class AuthRepositoryImpl extends AuthRepository {
  final _remoteAuthTokoDataSource = Get.find<RemoteAuthTokoDataSource>();

  final _remoteAuthDataSource = Get.find<RemoteAuth0DataSource>();

  final _localAuthDataSource = Get.find<LocalAuthDataSource>();

  @override
  Future<bool> checkAuthenticated() async {
    final token = await _localAuthDataSource.getAuth0Token();

    return token.isNotEmpty;
  }

  @override
  Future<String> getIdToken() async {
    return await _localAuthDataSource.getAuth0IdToken();
  }

  @override
  Future<String> getCMSToken() async {
    return await _localAuthDataSource.getCMSToken();
  }

  @override
  Future<String> getUsername() async {
    return await _localAuthDataSource.getAuth0Username();
  }

  @override
  getNotificationToken() {
    return _localAuthDataSource.getNotificationToken();
  }

  @override
  Future<DataState<LoginModel>> login({
    required LoginRequest request,
    bool fromLogin = false,
  }) {
    return _remoteAuthDataSource
        .login(LoginSource.grantType, request)
        .toDataState();
  }

  @override
  Future<DataState<ChallengeModel>> authenticatorChallenge({
    required AuthenticatorChallengeRequest request,
  }) {
    return _remoteAuthDataSource.authenticatorChallenge(request).toDataState();
  }

  @override
  Future<DataState<LoginModel>> verifyOtp({
    required VerifyOtpRequest request,
  }) {
    return _remoteAuthDataSource.verifyOtp(request).toDataState();
  }

  @override
  Future<DataState<EmptyModel>> changePassword({
    required EmailRequest request,
  }) async {
    try {
      await Auth0Service.instance.changePassword(request: request);
      return Future.value(DataState.success(EmptyModel()));
    } catch (e) {
      return Future.value(DataState.failed(UnexpectedError(cause: e)));
    }
  }

  @override
  Future<DataState<LoginModel>> exchangeTokoToken() async {
    final email = await _localAuthDataSource.getAuth0Username();
    final request = EmailRequest(email: email);

    return _remoteAuthTokoDataSource
        .tokenRequest(request)
        .toDataState(
          onSuccess: (data) async {
            await _localAuthDataSource.setTokoToken(data?.token);
          },
        );
  }

  @override
  Future<DataState<LoginModel>> verifyTokoToken() async {
    final token = await _localAuthDataSource.getTokoToken();
    final request = VerifyTokoTokenRequest(token: token);
    return _remoteAuthTokoDataSource.tokenVerify(request).toDataState();
  }

  @override
  Future<DataState<LoginModel>> getAuthorizeCMSToken() {
    final request = Auth0CMSRequest();
    return _remoteAuthDataSource
        .getAuthorizeCMSToken(request)
        .toDataState(
          onSuccess: (data) {
            _localAuthDataSource.setCMSToken(data?.token);
          },
        );
  }

  @override
  Future<DataState<LoginModel>> getAuthorizeNotificationToken() {
    final request = Auth0NotificationRequest();
    return _remoteAuthDataSource
        .getAuthorizeNotificationToken(request)
        .toDataState(
          onSuccess: (data) {
            _localAuthDataSource.setNotificationToken(data?.token);
          },
        );
  }

  @override
  Future<DataState<EmptyModel?>> logout({required LogoutRequest request}) {
    return _remoteAuthDataSource
        .logout(request)
        .toDataState(
          onSuccess: (_) async => await _localAuthDataSource.logout(),
        );
  }

  @override
  Future<void> resetLogin() async {
    return _localAuthDataSource.clearAll();
  }
}

