import 'package:auth0_flutter/auth0_flutter.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:ioh_ide_mobile/core/constants/default_value.dart';
import 'package:ioh_ide_mobile/models/requests/email/email_request.dart';

class Auth0Service {
  static Auth0Service? _instance;

  static Auth0Service get instance {
    _instance ??= Auth0Service();
    return _instance!;
  }

  static final _domain = dotenv.get("AUTH0_DOMAIN");
  static final _clientId = dotenv.get("AUTH0_CLIENT_ID");

  final _auth0 = Auth0(_domain, _clientId);

  Future<void> changePassword({required EmailRequest request}) async {
    try {
      final connection = dotenv.get("AUTH0_REALM_DATABASE");

      await _auth0.api.resetPassword(
        email: request.email ?? DefaultValue.empty,
        connection: connection,
      );
    } catch (e) {
      rethrow;
    }
  }

  Future<Credentials> refreshToken({required String refreshToken}) async {
    try {
      return await _auth0.api.renewCredentials(
        refreshToken: refreshToken,
        scopes: {"openid", "profile", "email", "offline_access"},
      );
    } catch (e) {
      rethrow;
    }
  }
}

