import 'package:dio/dio.dart';
import 'package:get/get.dart';
import 'package:ioh_ide_mobile/core/services/queue_request/queue_request.dart';
import 'package:ioh_ide_mobile/data/data_sources/network/app_dio.dart';

class RequestQueueService {
  static final RequestQueueService _instance = RequestQueueService._internal();

  factory RequestQueueService() => _instance;

  RequestQueueService._internal();

  final List<QueuedRequest> _queue = [];

  int retryCount = 0;

  void add(QueuedRequest req) {
    _queue.add(req);
  }

  Future<void> retryAll() async {
    retryCount++;

    final dio = Get.find<AppDio>();
    final List<QueuedRequest> stillFailed = [];

    for (var queued in _queue) {
      try {
        final res = await dio.requestUri(
          queued.request.uri,
          data: queued.request.data,
          options: Options(
            method: queued.request.method,
            headers: queued.request.headers,
            extra: queued.request.extra,
          ),
        );
        if (!queued.completer.isCompleted) {
          queued.completer.complete(res);
        }
      } catch (e) {
        if (!queued.completer.isCompleted) {
          queued.completer.completeError(e);
        }
        stillFailed.add(queued);
      }
    }

    _queue
      ..clear()
      ..addAll(stillFailed);
  }

  bool get hasRequests => _queue.isNotEmpty;

  void clear() => _queue.clear();
}

