import 'package:dio/dio.dart';

sealed class NetworkError {
  const NetworkError();
}

class DioExceptionError extends NetworkError {
  final DioException cause;

  const DioExceptionError({required this.cause});
}

class UnexpectedError extends NetworkError {
  final Object cause;

  const UnexpectedError({required this.cause});
}

extension NetworkErrorExtension on NetworkError {
  NetworkError dioError(void Function(DioExceptionError error) block) {
    if (this is DioExceptionError) {
      block(this as DioExceptionError);
    }
    return this;
  }

  NetworkError unexpectedError(void Function(UnexpectedError error) block) {
    if (this is UnexpectedError) {
      block(this as UnexpectedError);
    }
    return this;
  }
}

