import 'dart:io';

import 'package:flutter/cupertino.dart';
import 'package:flutter/foundation.dart';
import 'package:get/get.dart';
import 'package:ioh_ide_mobile/app/resources/app_images.dart';
import 'package:ioh_ide_mobile/core/services/localization/language.dart';
import 'package:ioh_ide_mobile/view/widgets/bottomsheet/information_bottom_sheet.dart';
import 'package:jailbreak_root_detection/jailbreak_root_detection.dart';
import 'package:safe_device/safe_device.dart';

abstract class BaseController extends GetxController {
  bool observerRegistered = false;

  List<Worker> observer = [];

  @override
  void onReady() {
    if (kReleaseMode) checkDeviceSafe();
    super.onReady();
  }

  @override
  void onClose() {
    for (var worker in observer) {
      worker.dispose();
    }
    super.onClose();
  }

  Future<void> checkDeviceSafe() async {
    bool isDeviceSave = true;

    final isNotTrust = await JailbreakRootDetection.instance.isNotTrust;
    final isJailBroken = await JailbreakRootDetection.instance.isJailBroken;
    final isRealDevice = await JailbreakRootDetection.instance.isRealDevice;
    final isRealDeviceSafeDevice = await SafeDevice.isRealDevice;
    final isDevMode = await JailbreakRootDetection.instance.isDevMode;

    if (isNotTrust ||
        isJailBroken ||
        isDevMode ||
        !isRealDevice ||
        !isRealDeviceSafeDevice) {
      isDeviceSave = false;
    }

    if (!isDeviceSave) {
      if (Get.isBottomSheetOpen!) return;
      Get.bottomSheet(
        PopScope(
          canPop: false,
          child: InformationBottomSheet(
            image: AppImages.imgError,
            title: Language.labelDeviceNotSafeTitle.tr,
            description: Language.labelDeviceNotSafeDescription.tr,
            buttonTitle: Language.labelDeviceNotSafeConfirm.tr,
            onButtonTap: () {
              exit(0);
            },
          ),
        ),
        isDismissible: false,
        enableDrag: false,
      );
    }
  }
}

