import 'package:ioh_ide_mobile/core/constants/default_value.dart';

class DioErrorSource {
  static const int maxRetry = 3;

  static const List<String> handlePathBadRequest = [
    "/service/omnichannel/catalog/getCatalogProduct"
  ];

  static bool handleBadRequest(String url) {
    String path = url;

    if (url.contains("http") || url.contains("https")) {
      path = Uri.tryParse(url)?.path ?? DefaultValue.empty;
    }

    return handlePathBadRequest.contains(path);
  }
}

