import 'package:ioh_ide_mobile/data/data_sources/network/network_error.dart';

abstract class DataState<T> {
  const DataState();

  const factory DataState.loading() = Loading<T>;
  const factory DataState.success(T data) = Success<T>;
  const factory DataState.failed(NetworkError error) = Failed<T>;

  R when<R>({
    required R Function() loading,
    required R Function(T data) success,
    required R Function(NetworkError error) failed,
  }) {
    if (this is Loading<T>) return loading();
    if (this is Success<T>) return success((this as Success<T>).data);
    if (this is Failed<T>) return failed((this as Failed<T>).error);
    throw Exception('Unhandled state: $this');
  }
}

class Loading<T> extends DataState<T> {
  const Loading();

  @override
  bool operator ==(Object other) => other is Loading<T>;

  @override
  int get hashCode => runtimeType.hashCode;
}

class Success<T> extends DataState<T> {
  final T data;

  const Success(this.data);

  @override
  bool operator ==(Object other) => other is Success<T> && other.data == data;

  @override
  int get hashCode => data.hashCode;
}

class Failed<T> extends DataState<T> {
  final NetworkError error;

  const Failed(this.error);

  @override
  bool operator ==(Object other) => other is Failed<T> && other.error == error;

  @override
  int get hashCode => error.hashCode;
}

extension DataStateExtension<T> on DataState<T> {
  DataState<T> loading(void Function() block) {
    if (this is Loading<T>) {
      block();
    }
    return this;
  }

  DataState<T> success(void Function(T data) block) {
    if (this is Success<T>) {
      block((this as Success<T>).data);
    }
    return this;
  }

  DataState<T> failed(void Function(NetworkError failure) block) {
    if (this is Failed<T>) {
      block((this as Failed<T>).error);
    }
    return this;
  }
}

