  Future<String> refreshTokenIfNeeded(
    Future<String> Function() refreshLogic,
  ) async {
    // If there was a recent failure, don't retry immediately
    if (_lastFailureTime != null) {
      final timeSinceFailure = DateTime.now().difference(_lastFailureTime!);
      if (timeSinceFailure < _cooldownDuration) {
