      "suggested_code": "class TokenRefreshService {
  static final TokenRefreshService _instance = TokenRefreshService._internal();
  factory TokenRefreshService() => _instance;

  TokenRefreshService._internal();

  Completer<String>? _completer;
  DateTime? _lastFailureTime;
  static const _cooldownDuration = Duration(seconds: 5);

  Future<String> refreshTokenIfNeeded(
    Future<String> Function() refreshLogic,
  ) async {
    // If there was a recent failure, don't retry immediately
    if (_lastFailureTime != null) {
      final timeSinceFailure = DateTime.now().difference(_lastFailureTime!);
      if (timeSinceFailure < _cooldownDuration) {
        throw Exception('Token refresh failed recently, please wait ${_cooldownDuration.inSeconds}s');
      }
    }

    if (_completer != null) {
      // Another refresh is already in progress, wait for it
      return _completer!.future;
    }

    _completer = Completer<String>();

    try {
      final newToken = await refreshLogic();
      _lastFailureTime = null;  // Reset failure time on success
      _completer!.complete(newToken);
      return newToken;
    } catch (e) {
      _lastFailureTime = DateTime.now();  // Record failure time
      _completer!.completeError(e);
      rethrow;
    } finally {
      _completer = null;
    }
  }

  // Call this on successful login/logout to reset state
  void reset() {
    _completer = null;
    _lastFailureTime = null;
  }
}",
